            checksum: "d896659d3a9f6c79e398af09fb20e2b859c394c5138c8d358e5f417335c36490"
        ),
        .binaryTarget(
            name: "AgentforceCustomization",
            url: "https://github.com/salesforce/AgentforceMobileSDK-iOS/releases/download/19.29.0-rc2/AgentforceMobileCustomization-262-3-RC2-spm.xcframework.zip",
            checksum: "cb5a279d16ee7aaf3b26b472cf6bc2c008fbd6787e0f17716e4e6e56ad440d34"
        ),
        .target(
            name: "AgentforceSDKTarget",
            dependencies: [
                "AgentforceSDK",
                "AgentforceService",
                // swift-markdown-ui intentionally omitted (SDK imports it as
